@js:
function parse(html, ys, num) {
    let a = org.jsoup.Jsoup.parse(html);
    let b = Array.from(a.selectFirst(ys).attributes());
    if (num)
    return b[num]?.toString().match(/"(.+)"/)?.[1];  
}

function parseeg(html, ys, eg) {
    let b = Array.from(html.selectFirst(ys).attributes());
    for(i in b){ 
       c = b[i]?.toString().match(/"(.+)"/)?.[1];
      	if(eg.test(c)){ return c}
    }
}

(() => {
    let od, sd;
    x = Array.from(java.getElements("class.BCsectionTwo-top-chapter"));

    od = src.match(/originalOrder = (\[.+?\])/);
    sd = x.map((c) => {
        return parse(c, "li", 2);
    });

    if (od || sd) {
        if (od) {
            od = JSON.parse(od[1]).reduce((arr, item) => {
                arr.push(item + 1);
                return arr;
            }, []);
            x = x.map((item) => ({
                title:
                    item.select("a").attr("data-real") != ""
                        ? item.select("a").attr("data-real")
                        : item.select("a").text(),
                href: item.select("a").attr("href")
            }));

        } else if (sd) {
            x = x.map((item) => (
              {
                title: parseeg(item, "li>a", /[\u4e00-\u9fff]/),
                href: java.base64Decode(parseeg(item, "li>a", /L2Jv/))
            }));
        }
        sot = od || sd;
        return x.sort((a, b) => {
            ia = x.indexOf(a);
            ib = x.indexOf(b);
            return sot[ia] - sot[ib];
        });
    }

    return x.map((item) => ({
        title: item.select("a").text(),
        href: item.select("a").attr("href")
    }));
})();
//java.log(JSON.stringify(x))

